#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeEngine: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = Engine

    public static func lift(_ handle: UInt64) throws -> Engine {
        return Engine(unsafeFromHandle: handle)
    }

    public static func lower(_ value: Engine) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> Engine {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: Engine, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeEngine_lift(_ handle: UInt64) throws -> Engine {
    return try FfiConverterTypeEngine.lift(handle)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeEngine_lower(_ value: Engine) -> UInt64 {
    return FfiConverterTypeEngine.lower(value)
}




/**
 * What a delete will move, before it moves it.
 *
 * `op_id` is the identity SwiftUI's `.sheet(item:)` needs — and it is the right one, because
 * it names the operation rather than the view.
 */
public struct DeletePlan: Equatable, Hashable {
    /**
     * Names the operation, so the dialog can say what it is about to do.
     */
    public var opId: String
    public var photographs: UInt32
    public var files: UInt32
    public var bytes: UInt64
    /**
     * Conditions worth saying out loud: a cross-volume copy, a file that has gone missing.
     */
    public var warnings: [String]
    /**
     * Reasons this selection cannot be moved. **Non-empty means nothing will move.**
     */
    public var refusals: [String]

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * Names the operation, so the dialog can say what it is about to do.
         */opId: String, photographs: UInt32, files: UInt32, bytes: UInt64, 
        /**
         * Conditions worth saying out loud: a cross-volume copy, a file that has gone missing.
