/**
 * How far a pass has got.
 *
 * A callback rather than a poll: a face pass runs for an hour, and a UI that can only ask
 * "are we there yet" has nothing to show for the first fifty-nine minutes.
 */
public protocol Progress: AnyObject, Sendable {
    
    /**
     * Called on the thread running the pass.
     *
     * **Do not call back into the `Engine` from here.** Hop to the actor that owns your state
     * and return; the pass is holding a connection and a callback that waits on it will wait
     * forever.
     *
     * `total` is `0` while scanning — the size of a tree is not known until the walk
     * finishes, and a determinate bar over an unknown total is a bar that lies.
     *
     * `current` is the file being worked on, or empty for stages that have no single file.
     *
     * **Returns whether to keep going.** A callback that can only be listened to cannot stop
     * anything, and a face pass over a large library is tens of minutes. Both passes commit
     * each file as they go, so stopping loses nothing — the work list is the catalog, and the
     * next pass resumes from where this one stopped.
     */
    func onProgress(done: UInt32, total: UInt32, stage: String, current: String)  -> Bool
    
}


// Put the implementation in a struct so we don't pollute the top-level namespace
fileprivate struct UniffiCallbackInterfaceProgress {

    // Create the VTable using a series of closures.
    // Swift automatically converts these into C callback functions.
    //
    // Store the vtable directly.
    static let vtable: UniffiVTableCallbackInterfaceProgress = UniffiVTableCallbackInterfaceProgress(
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            do {
                try FfiConverterCallbackInterfaceProgress.handleMap.remove(handle: uniffiHandle)
            } catch {
                print("Uniffi callback interface Progress: handle missing in uniffiFree")
            }
        },
        uniffiClone: { (uniffiHandle: UInt64) -> UInt64 in
            do {
                return try FfiConverterCallbackInterfaceProgress.handleMap.clone(handle: uniffiHandle)
            } catch {
                fatalError("Uniffi callback interface Progress: handle missing in uniffiClone")
            }
        },
        onProgress: { (
            uniffiHandle: UInt64,
            done: UInt32,
            total: UInt32,
            stage: RustBuffer,
            current: RustBuffer,
            uniffiOutReturn: UnsafeMutablePointer<Int8>,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> Bool in
                guard let uniffiObj = try? FfiConverterCallbackInterfaceProgress.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return uniffiObj.onProgress(
                     done: try FfiConverterUInt32.lift(done),
                     total: try FfiConverterUInt32.lift(total),
                     stage: try FfiConverterString.lift(stage),
                     current: try FfiConverterString.lift(current)
                )
            }

            
            let writeReturn = { uniffiOutReturn.pointee = FfiConverterBool.lower($0) }
            uniffiTraitInterfaceCall(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn
            )
        }
    )

    // Rust stores this pointer for future callback invocations, so it must live
    // for the process lifetime (not just for the init function call).
    //
    // `nonisolated(unsafe)` is needed under Swift 6 strict concurrency.
    // This is safe because the pointee is initialized once during static init
    // and never mutated by either side of the FFI.  Its fields are C function pointers.
    nonisolated(unsafe) static let vtablePtr: UnsafePointer<UniffiVTableCallbackInterfaceProgress> = {
        let ptr = UnsafeMutablePointer<UniffiVTableCallbackInterfaceProgress>.allocate(capacity: 1)
        ptr.initialize(to: vtable)
        return UnsafePointer(ptr)
    }()
}

private func uniffiCallbackInitProgress() {
    uniffi_chaff_ffi_fn_init_callback_vtable_progress(UniffiCallbackInterfaceProgress.vtablePtr)
}

